/* ============================================================
   FOOD LOG — leftover data only (roadmap A1)
   Food logging left Ironlog in 0.25.0 for its own app. A log that existed
   before that is kept, untouched and unshown, until it has been exported
   (Settings -> Data) or removed (Clear data). Nothing here logs food.
   ============================================================ */
export function hasFoodData() { return !!((S.foods || []).length); }
function foodExportData() {
  const st = S.settings;
  const entries = [...(S.foods || [])].sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
  return {
    format: 'ironlog-food-log', formatVersion: 1,
    exportedAt: new Date().toISOString(), appVersion: APP_VERSION,
    units: { energy: 'kcal', protein: 'g', carbs: 'g', fat: 'g', fibre: 'g' },
    targets: { kcal: st.kcalTarget, protein: st.proteinTarget, carbs: st.carbTarget, fat: st.fatTarget },
    goal: st.nutritionGoal || null,
    // src: 'manual' typed in, 'ai' parsed by Claude, 'table'/'offline' from the built-in tables
    entries: entries.map(f => ({ id: f.id, date: f.date, meal: f.meal || 'Snacks', name: f.name, serving: f.serving || '',
      kcal: f.kcal || 0, protein: f.p || 0, carbs: f.c || 0, fat: f.f || 0, fibre: f.fib || 0, source: f.src || 'manual' })),
  };
}
function foodExportCsv(data) {
  const DQ = String.fromCharCode(34);   // the CSV quote, spelled out so no regex or literal needs escaping
  const q = v => {
    let s = v == null ? '' : String(v);
    if (typeof v === 'string' && /^'*[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?(e[+-]?\d+)?$/i.test(s)) s = "'" + s;   // formula guard, as csvCell
    return [',', DQ, '\n', '\r'].some(c => s.includes(c)) ? DQ + s.split(DQ).join(DQ + DQ) + DQ : s;
  };
  const head = ['date', 'meal', 'name', 'serving', 'kcal', 'protein_g', 'carbs_g', 'fat_g', 'fibre_g', 'source'];
  const rows = data.entries.map(e => [e.date, e.meal, e.name, e.serving, e.kcal, e.protein, e.carbs, e.fat, e.fibre, e.source].map(q).join(','));
  return '﻿' + [head.join(','), ...rows].join('\r\n') + '\r\n';   // BOM so Excel reads the £ and accents right
}
export function openFoodExport() {
  const d = foodExportData();
  const n = d.entries.length;
  const days = new Set(d.entries.map(e => e.date)).size;
  modal({
    title: 'Export food log',
    body: `<div class="sub" style="margin-bottom:10px">Food logging has moved out of Ironlog into its own app. Your old food log
        is still here — save it, then remove it from Clear data. Training data isn't affected.</div>
      <div class="stats grid3" style="margin-bottom:12px">
        <div class="stat"><div class="k">Entries</div><div class="v">${n}</div></div>
        <div class="stat"><div class="k">Days</div><div class="v">${days}</div></div>
        <div class="stat"><div class="k">Targets</div><div class="v" style="font-size:15px">${d.targets.kcal ? `${d.targets.kcal} kcal` : 'none'}</div></div>
      </div>
      <button class="btn primary wide" id="fxJson" style="margin-bottom:8px" ${n || d.targets.kcal ? '' : 'disabled'}>Save food log (JSON)</button>
      <div class="sub" style="margin:-2px 0 10px">Everything — entries, targets and goal. This is the file the new food app will import.</div>
      <button class="btn wide" id="fxCsv" ${n ? '' : 'disabled'}>Save as spreadsheet (CSV)</button>
      <div class="sub" style="margin-top:4px">Entries only, one row each, for Excel or Google Sheets.</div>`,
    foot: `<button class="btn ghost" data-close>Close</button>`,
    onOpen: bg => {
      $('#fxJson', bg).onclick = () => { saveBlob(JSON.stringify(foodExportData(), null, 2), 'application/json', `ironlog-food-${today()}.json`); S.settings.foodExportedAt = Date.now(); save(); toast('Food log saved', 'green'); };
      $('#fxCsv', bg).onclick = () => { saveBlob(foodExportCsv(foodExportData()), 'text/csv', `ironlog-food-${today()}.csv`); toast('Spreadsheet saved', 'green'); };
    },
  });
}
